window.CONTENT_PARTS = window.CONTENT_PARTS || [];
window.CONTENT_PARTS.push({ lang: "en", units: [], extends: [

{ id: "en-golden", blocks: [
  { type: "chips", title: "More golden lines: openings that hook", groups: [
    { title: "Open with a sound", words: ["Thud. The box of eggs hit the supermarket floor.","The alarm clock shrilled, and I knew at once that something was wrong: it was already 7.15.","Bang, bang, bang. Someone was knocking on our door at midnight.","The school bell rang, but nobody in 3B moved.","A loud splash, a yelp, and then laughter drifted up from the pool.","The phone buzzed on the table, and Mum’s face changed as she read the message.","Ding-dong! The doorbell rang twice, then three times, then would not stop.","A strange scratching noise was coming from inside my school bag.","The whistle blew, and fifty pupils froze in the middle of the field.","“Pssst!” Someone was hiding behind the pillar at the void deck.","Somewhere in the block, a baby was crying, and it had been crying for an hour.","Crack! The ruler snapped in two, and the whole class went quiet."],
      ex: "Thud. The box of eggs hit the supermarket floor, and every shopper in the aisle turned to look at me.",
      note: "A sound on its own grabs the reader. Follow it straight away with what made the sound." },
    { title: "Open with a line of speech", words: ["“Don’t open that box,” Ah Ma said, but it was already too late.","“Who took my last packet of chips?” my brother roared.","“Guess what?” Aisha whispered. “There’s a new boy, and he’s sitting next to you.”","“Are you sure this is the right bus?” I asked. Dad did not answer.","“Five more minutes,” I begged, pulling the blanket over my head.","“Hold this for me, and whatever you do, don’t let go,” Uncle Raju said.","“Put away your books,” Mrs Lim said. “We’re having a surprise spelling test.”","“It’s only a small cut,” I said, trying not to look at the tissue.","“Mum, I think I broke something.”","“Nobody move,” the guide said quietly. “There’s a snake on the path.”","“Happy birthday!” I shouted, but the flat was empty.","“Can you keep a secret?” Jun Hao asked, and I nodded far too quickly."],
      ex: "“Can you keep a secret?” Jun Hao asked, and I nodded far too quickly. By recess, I wished I had said no.",
      note: "Start with someone speaking, then add ONE line of action. The reader is dropped right into the scene." },
    { title: "Open in the middle of the action", words: ["I was halfway up the climbing wall when my foot slipped.","By the time I reached the bus stop, the bus was already pulling away.","The cake was in the oven, the guests were on their way, and the oven had just switched itself off.","I had exactly three minutes to find my name tag before the concert started.","The ball was still rolling towards the drain when I started running.","Water was already lapping at my ankles when I realised the tap was still on.","Grandpa’s birdcage door was swinging open, and the cage was empty.","I had just pressed the lift button when the lights in the lobby went out.","My hand was in the biscuit tin when the kitchen light flicked on.","We were twenty metres from the shore when the kayak began to tip.","The last page of my project fluttered out of my hands and over the corridor railing.","I was still in my pyjamas when the school bus honked downstairs."],
      ex: "I was still in my pyjamas when the school bus honked downstairs. I grabbed my bag, my shoes and, by mistake, my sister’s water bottle.",
      note: "Skip the boring part (waking up, brushing teeth). Begin at the moment things start to happen." }
  ]},
  { type: "chips", title: "More golden lines: endings that linger", groups: [
    { title: "End on one small picture", words: ["The little paper boat bobbed along the canal until I could not see it any more.","On my desk, the cracked trophy still stands, glued back together.","Grandpa’s slippers still sit by the door, side by side.","The plaster on my knee had a cartoon frog on it, and I kept it on for a week.","The kite now hangs on my bedroom wall, its tail a little torn.","Two empty cups of bubble tea sat on the bench where we had made up.","The stray cat was curled up on our doormat, as if it had always lived there.","My old running shoes, still muddy from the race, sit at the back of the cupboard.","The rain had washed the chalk drawings away, but I remembered every one.","The last firework faded, leaving a thin trail of smoke against the stars.","In the photo, we are all squinting at the sun and laughing at something nobody can remember.","Her note is folded in my wallet, soft from being opened so many times."],
      ex: "Grandpa’s slippers still sit by the door, side by side. Nobody in our family has the heart to move them.",
      note: "Instead of explaining the lesson, show one object that holds the whole story." },
    { title: "End with a last line of speech", words: ["“Same time next week?” Wei Ming asked. I grinned. “Same time next week.”","“Next time,” Dad said, handing me the map, “you can be the navigator.”","“Thank you,” the old lady said, and that was all I needed to hear.","“You know what?” Mum said, switching off the light. “I’m proud of you.”","“Race you home!” Priya shouted, and for once, I let her win.","“Let’s never do that again,” Jun Hao groaned, and we both burst out laughing.","“Do you forgive me?” I asked. She handed me half of her curry puff.","“Well,” Grandma said, looking at the burnt cookies, “at least the kitchen smells nice.”","“Is it over?” my sister whispered. “Yes,” I said. “It’s over.”","“See you tomorrow,” he said, and this time I knew he meant it.","“Maybe,” Coach said, “you’re ready for the team after all.”"],
      ex: "“Do you forgive me?” I asked. She handed me half of her curry puff. That was her way of saying yes.",
      note: "A short last line of speech can sum up a story better than a long lesson." },
    { title: "End by looking ahead", words: ["Tomorrow, I would have to face the class, but tonight, I let myself rest.","I still have a long way to go, but at least I have started.","Somewhere out there, the owner of that wallet is having a better day because of us.","The new term starts on Monday, and for the first time, I cannot wait.","I have already marked next year’s race on the calendar.","One day, I hope to do for someone else what she did for me.","Who knows? Maybe next time, I will be the one helping a lost child find her way.","Grandpa says he will teach me his famous fish soup next. I have a feeling it will not go smoothly.","I put the bicycle back in the storeroom, ready for tomorrow’s practice.","Next year, I will be the one standing on that stage, and I will be ready."],
      ex: "I put the bicycle back in the storeroom, ready for tomorrow’s practice. This time, I would not need Dad to hold on.",
      note: "Looking ahead tells the reader the story has changed your character for good." }
  ]},
  { type: "chips", title: "More golden lines: Easy – P1/P2", groups: [
    { title: "A happy day", words: ["The sun was shining, and I was smiling too.","I jumped up and down and clapped my hands.","Grandpa gave me a high five.","We laughed and laughed until our tummies hurt.","I licked my ice cream before it could melt.","My friend held my hand, and we ran to the swings.","I wished the day would never end.","Dad lifted me up so that I could see.","I hummed a song all the way home.","The puppy licked my face, and I giggled.","We shared our snacks under the big tree.","I was so happy that I could not sit still."],
      ex: "The puppy licked my face, and I giggled. I wished the day would never end.",
      note: "Easy – P1/P2. Short lines are fine. Say who, what happened and how you felt." },
    { title: "Oh no!", words: ["Oh no! My ice cream fell on the floor.","I tripped and scraped my knee.","My balloon floated up into the sky.","The glass fell and broke into pieces.","I could not find my mum.","It started to rain, and I had no umbrella.","My pencil box fell open, and everything rolled away.","I spilt my drink all over my book.","The bus drove off without us.","My tooth was wobbly, and then it fell out!","I left my homework at home.","My little brother tore my drawing."],
      ex: "Oh no! My balloon floated up into the sky. I watched it until it was just a tiny red dot.",
      note: "Easy – P1/P2. Every story needs an “Oh no!” moment. Pick one, then say what you did next." },
    { title: "Feelings in short lines", words: ["My cheeks went red.","I wiped my eyes with my sleeve.","Tears filled my eyes.","My legs were shaking.","I hid behind Mum.","I held my breath.","I gave a big, wide smile.","I stamped my foot.","I let out a big sigh.","I hugged my teddy bear tightly.","I peeped out from behind my fingers.","I felt warm inside."],
      ex: "My legs were shaking. I hid behind Mum and held on to her dress.",
      note: "Easy – P1/P2. Show the feeling with your body instead of only writing “I was scared”." }
  ]},
  { type: "chips", title: "More golden lines: paragraph starters", groups: [
    { title: "Moving the clock forward", words: ["Straight after lunch, …","By the time recess came, …","That evening, when Dad came home, …","Early on Monday morning, …","Two weeks passed, and …","Soon, the whole class knew.","Within a week, …","Later that night, …","On the day of the race, …","Just as we were about to leave, …","When the last bell rang, …","Five minutes into the journey, …"],
      ex: "By the time recess came, the whole class knew about the broken window.",
      note: "Each new paragraph needs a signpost. A time phrase tells the reader how much time has passed." },
    { title: "Moving to the problem", words: ["Everything was going to plan, until …","It was meant to be an ordinary Saturday.","At first, nobody noticed.","Then I heard it: …","That was when I saw the smoke.","The trouble began with a single text message.","Halfway through the performance, …","I should have read the instructions first.","It all started with a dare.","Nobody expected what happened next.","But not everyone was smiling.","There was just one problem."],
      ex: "Everything was going to plan, until Wei Ming tripped over the microphone cable.",
      note: "Use one of these to start the paragraph where the trouble begins." },
    { title: "Moving to the ending", words: ["Once the excitement had died down, …","By the end of the week, …","After everyone had gone home, …","Much later, when I told Mum the whole story, …","By the next day, everyone had forgotten, except me.","It took a long time for my hands to stop shaking.","Now, whenever I …","Months have passed since that day, but …","That night, as I lay in bed, …","As we packed up, …","Things went back to normal, or almost.","I never did find out who …"],
      ex: "I never did find out who left the umbrella at my door, but I still use it every rainy day." }
  ]},
  { type: "chips", title: "More golden lines: moving house and new neighbours", groups: [
    { title: "Moving house", words: ["Our whole life was packed into forty cardboard boxes.","I wrote my name inside my cupboard so that the flat would remember me.","The empty rooms echoed when I said goodbye.","Dad taped the last box shut, and the flat suddenly looked like a stranger’s.","The new flat smelt of fresh paint and nothing else.","I lay in my new room, listening to sounds I did not know yet.","From the window, I could see a different playground, full of children I did not know.","The movers carried our sofa down the corridor, grunting at every corner.","It took me a week to stop pressing the wrong lift button.","Slowly, the boxes disappeared and the new flat began to feel like home.","I kept my old house key, even though it would never open anything again.","On moving day, the lift was booked, the corridor was blocked and everyone was grumpy."],
      ex: "Dad taped the last box shut, and the flat suddenly looked like a stranger’s. I ran my hand along the wall one last time." },
    { title: "New neighbours", words: ["A removal lorry was parked outside our block all morning.","The door opposite ours had been shut for months, until one morning it was wide open.","A small pair of school shoes appeared on the shoe rack next door.","Our new neighbours came over with a plate of curry puffs to say hello.","The boy next door gave me a shy wave over the corridor plants.","At first, the new family kept to themselves.","Their dog barked at me every time I passed, until I learnt its name.","Mum sent me over with a tub of soup, and I came back with a box of kuih.","We met at the lift every morning and soon ran out of excuses not to talk.","Uncle Hassan next door taught me how to fix the chain on my bicycle.","When they went on holiday, we watered their plants and fed their fish.","By Hari Raya, their door was always open to us, and ours to them."],
      ex: "Mum sent me over with a tub of soup, and I came back with a box of kuih. That was how our friendship with the Hassans began." }
  ]},
  { type: "chips", title: "More golden lines: screens and gadgets", groups: [
    { title: "Too much screen time", words: ["Just one more level, I told myself, for the fifth time.","The glow of the tablet lit up my face under the blanket.","I had been staring at the screen for so long that my eyes felt dry and scratchy.","Mum called me for dinner three times, and I did not hear her once.","When the Wi-Fi went down, I had no idea what to do with myself.","Outside, my friends were playing football, and I was watching strangers play it on a screen.","My thumbs ached, but I could not stop scrolling.","Dad held out his hand. “Phone, please.” I handed it over with a sigh.","Without the screen, the afternoon stretched out, long and empty, then slowly filled up with other things.","That week, I read three books, built a fort and actually talked to my sister.","I set a timer for thirty minutes, and this time, I kept my promise.","I looked up from the game and realised it was already dark outside."],
      ex: "Mum called me for dinner three times, and I did not hear her once. The fourth time, she switched off the Wi-Fi." },
    { title: "Trouble in the group chat", words: ["My phone buzzed and buzzed with messages from the class chat.","Someone had posted a photo of Wei Ming without asking him.","The laughing faces kept coming, and none of them were kind.","I typed a reply, deleted it, and typed it again.","I knew that once I pressed send, I could never take it back.","Nobody in the chat said anything, so I did.","“That’s not funny,” I typed, and pressed send before I could change my mind.","One by one, the others stopped posting.","I showed the messages to Mum, and she helped me decide what to do.","The next day, the photo was gone, and someone had said sorry.","Being kind matters just as much on a screen as it does face to face.","Before I post anything now, I ask myself: would I say this to their face?"],
      ex: "Nobody in the chat said anything, so I did. “That’s not funny,” I typed, and pressed send before I could change my mind.",
      note: "Good for compositions about courage, kindness or a difficult choice." }
  ]},
  { type: "chips", title: "More golden lines: brothers and sisters", groups: [
    { title: "Squabbles", words: ["“Mum! He’s looking at me again!”","We drew an invisible line down the middle of the back seat.","My sister borrowed my favourite T-shirt without asking, again.","The remote control was the most fought-over object in our flat.","He repeated everything I said in a squeaky voice until I wanted to scream.","We both reached for the last dumpling at exactly the same time.","“She started it!” we both shouted.","Mum sent us to opposite ends of the flat to cool down.","I slammed my bedroom door, and a moment later, he slammed his.","By dinner, we had forgotten what we were fighting about.","He knocked on my door holding two ice-cream sticks, and that was his way of saying sorry.","We argue every day, but nobody else is allowed to be mean to him."],
      ex: "We both reached for the last dumpling at exactly the same time. Neither of us let go." },
    { title: "Looking out for a little one", words: ["My baby sister fell asleep on my shoulder, and I did not dare to move.","I held my little brother’s hand tightly as we crossed the road.","I knelt down, wiped her tears and said, “Let’s fix it together.”","He followed me everywhere, like a small, noisy shadow.","I read him the same bedtime story for the twentieth time and still did the funny voices.","She tried to copy my handwriting, her tongue poking out in concentration.","When the thunder boomed, he crept into my bed, and I let him stay.","I gave him the bigger half of the biscuit when nobody was watching.","On his first day of school, I waited at the gate so that he would see a familiar face.","Teaching him to tie his shoelaces took a whole week and a lot of patience.","“You’re the best kor kor in the world,” he mumbled sleepily.","I never told her, but I liked being the one she ran to."],
      ex: "When the thunder boomed, he crept into my bed, and I let him stay. I pretended I was not scared too." }
  ]},
  { type: "chips", title: "More golden lines: group work and class jobs", groups: [
    { title: "Working in a group", words: ["Everybody had an idea, and everybody was talking at once.","Jun Hao wanted to build a volcano; Aisha wanted to make a poster.","One member of our group did nothing but draw cartoons in the margin.","We divided the work into four parts and wrote our names beside each one.","Our model kept collapsing, so we added more ice-cream sticks.","The night before the deadline, our group chat was still buzzing at ten.","I bit back an angry reply and suggested we take a vote instead.","When Mei Ling finally shared her idea, it was the best one we had heard.","We practised our presentation in the corridor until the words came out smoothly.","Our hands shook as we carried the model to the front of the class.","The project was not perfect, but every one of us had a part in it.","I learnt that listening is just as important as having good ideas."],
      ex: "Everybody had an idea, and everybody was talking at once. I bit back an angry reply and suggested we take a vote instead." },
    { title: "Class jobs and duties", words: ["As class monitor, I had to keep the class quiet, and nobody made it easy.","Every Tuesday, it was my turn to wipe the whiteboard and sweep under the desks.","I collected thirty-six worksheets and counted them twice.","Being the line leader meant I had to walk slowly, even when I wanted to run.","I watered the class plants every morning, and one of them finally flowered.","The class hamster was my responsibility for the whole weekend.","I made sure the lights and fans were off before I locked the door.","A small job done well every day is still something to be proud of.","Our class won the Cleanest Classroom award, and we cheered as if it were the World Cup.","I handed out the exercise books, matching each name to a face.","At first I hated the job, but by the end of the year I was sad to give it up.","When the teacher stepped out, thirty pairs of eyes turned to me, the monitor."],
      ex: "The class hamster was my responsibility for the whole weekend. By Sunday night, I had checked his water bottle about fifty times." }
  ]},
  { type: "chips", title: "More golden lines: learning a new skill", groups: [
    { title: "Wobbly beginnings", words: ["Dad held the back of my bicycle seat as I pedalled shakily along the park connector.","I clung to the swimming float and would not let go.","My first pancake looked more like a map of an island.","The recorder let out a squeak that made the whole class giggle.","I wobbled, wobbled and toppled sideways onto the grass.","My stitches were so loose that the whole row unravelled.","Every time I tried to skip, the rope caught on my ankles.","The chopsticks kept crossing and dropping the peanut.","I swallowed a mouthful of pool water and came up coughing.","“Keep your eyes up, not on your feet,” Coach reminded me.","My first painting turned muddy because I had mixed every colour together.","I felt silly, but I tried again."],
      ex: "I wobbled, wobbled and toppled sideways onto the grass. I felt silly, but I tried again." },
    { title: "The breakthrough moment", words: ["I looked back and saw that Dad had let go a long way behind me.","My feet left the bottom of the pool, and I was swimming.","The rope swung over my head and under my feet ten times in a row.","For the first time, the tune sounded like a real song.","I flipped the pancake, and it landed back in the pan in one piece.","The chopsticks closed round the peanut, and I held it up like a prize.","Suddenly, all the hours of practice clicked into place.","I could not stop grinning as I cycled a whole lap without stopping.","Coach gave a short nod, and I knew I had got it right.","I did it again, just to make sure it was not luck.","What had seemed impossible a month ago now felt easy.","“Look, Mum, no hands!” I shouted, and then quickly put them back."],
      ex: "I looked back and saw that Dad had let go a long way behind me. I wobbled once, then kept pedalling." }
  ]},
  { type: "chips", title: "More golden lines: showing time passing (P4 and up)", groups: [
    { title: "Hours and days slipping by", words: ["The shadows on the field grew longer, and still we kept practising.","By the time we looked up, the canteen aunties were stacking the chairs.","Days turned into weeks, and the seedling grew taller than my ruler.","The calendar on the fridge filled up with crosses as the big day drew nearer.","The ice in my drink had melted into a watery puddle.","Morning became afternoon, and the queue barely moved.","Week after week, the jar of coins grew heavier.","The streetlights flickered on while we were still searching.","By the end of the holidays, my skin had turned two shades darker.","My once-shiny shoes were scuffed and grey by the end of the term.","By the time I finished, my tea had gone cold.","The months crept by, and the little kitten grew into a lazy, round cat."],
      ex: "Week after week, the jar of coins grew heavier. By December, I could barely lift it.",
      note: "P4 and up. Show time passing through something that changes, instead of just writing “after a long time”." },
    { title: "Seasons of the school year", words: ["In January, the new textbooks still smelt of fresh paper.","By March, our pencil cases were already missing half their pencils.","The June holidays flew by in a blur of swimming, tuition and sleeping in.","When the exam timetable went up, the classroom grew strangely quiet.","In the final weeks of the year, the corridors buzzed with holiday plans.","By November, our classroom walls were bare again, ready for the next class.","Each term, my school shorts got a little shorter on me.","On the last day, we squeezed six years of memories into one autograph book.","By the end of Primary Four, the scary new building had become our second home.","Every year, the seats in the hall seemed to shrink a little."],
      ex: "In January, the new textbooks still smelt of fresh paper. By November, they were dog-eared and covered in doodles.",
      note: "P4 and up. Good for stories that cover a whole year, such as making a new friend or working towards a goal." }
  ]},
  { type: "chips", title: "More golden lines: stretch sentences (P4 and up)", groups: [
    { title: "Then and now, this and that", words: ["Last year, I hid behind Mum at the gate; this year, I waved goodbye without looking back.","The hall that had roared with cheers was now silent and littered with streamers.","An hour ago, we had been laughing; now, nobody would meet anyone’s eyes.","Outside, the sun was shining. Inside, I could feel a storm coming.","Everyone else was celebrating, but I stood alone with the broken medal in my hand.","The race took me one minute to run and a whole year to prepare for.","He looked tough, but his hands trembled as he held the kitten.","The flat was full of balloons and music, yet the one person I wanted to see was missing.","At the start, we were four strangers; by the end, we were a team.","The test was only one page long, but it felt like a whole book."],
      ex: "At the start, we were four strangers; by the end, we were a team. Nobody wanted to be the first to leave.",
      note: "P4 and up. Putting two opposite things side by side makes both of them stand out." },
    { title: "Groups of three", words: ["I grabbed my bag, my bottle and my brother, and ran.","Mum checked the stove, the windows and the door, twice each.","The stall smelt of garlic, chilli and something sweet I could not name.","We were tired, sunburnt and completely happy.","I looked left, I looked right, and then I saw him.","She walked in, put down her bag and burst into tears.","The lights flickered, the music stopped and the room went dark.","He was too proud to ask, too stubborn to quit and too tired to go on.","I said sorry once, twice, three times, but she would not look at me.","One step, one breath, one more step.","We searched under the beds, behind the sofa and inside every shoe.","Rice, curry and a lot of laughter filled the table."],
      ex: "We were tired, sunburnt and completely happy. Nobody said a word on the drive home from the beach.",
      note: "P4 and up. Three items sound complete and natural. Two feels short; five feels like a shopping list." },
    { title: "A long sentence, then a short one", words: ["The crowd was cheering, the music was blaring and the lights were flashing. I could not move.","I had practised every day for three months, through rain, tuition and sore fingers. It was not enough.","We searched the playground, the void deck and every staircase in the block. Nothing.","Mum had cooked all morning, laid the table and invited everyone. Then the phone rang.","I ran past the canteen, up the stairs and down the long corridor. Too late.","The whole class was laughing and pointing at the screen. Except Wei Ming.","For weeks, I had dreamt of this moment, planned it and pictured it. Now it was here.","She waited by the gate, checking her watch every minute. He never came."],
      ex: "We searched the playground, the void deck and every staircase in the block. Nothing.",
      note: "P4 and up. A short sentence after a long one makes the reader stop and feel it. Use it once or twice in a story, not in every paragraph." }
  ]},
  { type: "table", title: "More golden lines: plain → vivid upgrades", head: ["Plain", "Golden"], weakCol: 0, rows: [
    ["It was hot.", "The metal slide burnt the backs of my legs."],
    ["I was nervous.", "I read the first line of my speech five times and still could not remember it."],
    ["She was angry.", "She put down her spoon very slowly and did not say a word."],
    ["He ran fast.", "He shot across the field, his bag bouncing on his back."],
    ["The food was nice.", "I scraped my plate clean and looked hopefully at the pot."],
    ["I was tired.", "I fell asleep on the bus, my shoes still dusty from the trail."],
    ["It was messy.", "Toys, socks and half-eaten biscuits covered every inch of the floor."],
    ["I was surprised.", "I read the message twice to make sure I had not imagined it."],
    ["The dog was happy.", "The dog spun in circles, chasing its own wagging tail."],
    ["It was a big crowd.", "All I could see were backs, elbows and the tops of heads."],
    ["She was kind.", "She gave me her umbrella and walked to the bus stop in the rain."],
    ["I was bored.", "I counted the holes in one ceiling board. Ninety-two."],
    ["We were late.", "The gate was already shut, and the guard was tapping his watch."],
    ["I was sad.", "I sat on the bottom step and let my ice cream melt."]
  ]}
]},

{ id: "en-sentencebank", blocks: [
  { type: "chips", title: "More scenes: shops and malls", groups: [
    { title: "The shopping mall", words: ["Cold air rushed out to meet us as the glass doors slid open.","Shoppers glided up and down the escalators, laden with paper bags.","Music thumped from a clothes shop, and a sales assistant smiled at the door.","The food court was a maze of trays, queues and glowing menu boards.","A giant screen in the atrium flashed adverts for phones and perfume.","Children pressed their faces against the window of the toy shop.","The polished floor reflected the lights like a frozen lake.","A long queue snaked out of the bubble tea shop.","Weekend crowds shuffled along the walkways at a snail’s pace.","In the basement, the smell of fresh bread and waffles drifted from every stall.","A security guard stood by the entrance, watching the crowd with folded arms.","At closing time, the shutters rattled down one by one, and the mall fell quiet."],
      ex: "Cold air rushed out to meet us as the glass doors slid open. Inside, the food court was a maze of trays, queues and glowing menu boards." },
    { title: "The supermarket", words: ["Trolleys clattered as shoppers wheeled them through the narrow aisles.","Shelves of instant noodles stretched from one end of the aisle to the other.","A fine mist puffed over the vegetables to keep them fresh.","The frozen-food section was so cold that I rubbed my arms.","A promoter in a red apron offered tiny cups of yoghurt to anyone passing.","The scanner at the checkout beeped, beeped, beeped.","A toddler sat in the trolley seat, chewing on a loaf of bread through the bag.","Neat pyramids of apples and pears gleamed under the bright lights.","Mum compared two bottles of soy sauce as if she were choosing a car.","Someone’s trolley had a squeaky wheel that we could hear from three aisles away.","At the end of the day, yellow stickers marked the bread down to half price.","The cashier packed our groceries with quick, practised hands."],
      ex: "Mum compared two bottles of soy sauce as if she were choosing a car, while I sneaked a packet of biscuits into the trolley." },
    { title: "Bookshops and stationery shops", words: ["The shop smelt of fresh paper and glue.","Colourful pens stood to attention in their plastic cups.","A boy sat cross-legged on the floor, reading a comic he had not paid for.","Stickers, erasers and pencil cases crowded every inch of the counter.","I ran my fingers along the spines, looking for my favourite author.","The shop was so quiet that I could hear the pages turning.","Glittery notebooks were stacked in neat towers near the till.","The owner peered at us over a mountain of exercise books.","Before the new term, the stationery shop was packed with parents holding long lists.","I tested every gel pen on the little scrap pad until Mum said, “Choose one.”"],
      ex: "I tested every gel pen on the little scrap pad until Mum said, “Choose one.” I chose the purple one, of course." }
  ]},
  { type: "chips", title: "More scenes: around the estate", groups: [
    { title: "Lifts and corridors", words: ["The lift creaked open, and the smell of somebody’s curry drifted out.","Pots of money plants and bougainvillea lined the corridor.","Shoe racks stood outside every door, crammed with slippers and school shoes.","Bamboo poles of laundry stuck out from the windows like flags.","The corridor light buzzed and flickered over the staircase.","A neighbour’s wind chime tinkled every time the breeze passed.","Children’s bicycles leaned against the railing, chained together.","The lift stopped at every single floor on the way down.","From the twelfth floor, the cars below looked like a box of crayons.","A notice in the lift reminded everyone not to litter.","The staircase smelt of fresh paint after the block was repainted.","Somewhere along the corridor, a radio was playing old Cantonese songs."],
      ex: "The lift stopped at every single floor on the way down. At the fourth, the smell of somebody’s curry drifted in." },
    { title: "The coffee shop in the morning", words: ["Kopi cups clinked against saucers as the uncles settled down for breakfast.","The drinks uncle poured the tea from a great height in a long, frothy stream.","Soft-boiled eggs wobbled in small saucers, waiting for a dash of soy sauce.","Newspapers rustled at every table.","Steam rose from the big metal urns behind the counter.","Birdcages hung from hooks under the roof, and the birds sang over the chatter.","An old auntie shuffled between the tables, collecting empty cups.","The smell of toast and kaya drifted onto the pavement.","Workers in boots gulped down their coffee and hurried off to the site.","The stall owners called out to their regulars by name.","A pigeon waited patiently under our table for crumbs.","By nine, the morning rush was over and the coffee shop was half empty."],
      ex: "The drinks uncle poured the tea from a great height in a long, frothy stream, and not a drop missed the cup." },
    { title: "The fitness corner and courts", words: ["Elderly aunties swung their arms on the exercise machines, chatting non-stop.","The basketball court echoed with thuds and shouts until late evening.","A man did pull-ups on the bars, counting under his breath.","The rubber floor of the fitness corner was still damp from the morning rain.","Teenagers sat at the edge of the court, sipping cans of isotonic drink.","Under the floodlights, moths swirled above the futsal court.","An uncle walked backwards round the track, clapping his hands as he went.","The jogging track looped round the block like a red ribbon.","Children took turns on the low bar, their legs kicking in the air.","Shoes squeaked on the court as the players changed direction.","A grandmother pushed a pram slowly along the path, round and round.","When the sun set, the court lights buzzed on and the game carried on."],
      ex: "An uncle walked backwards round the track, clapping his hands as he went, while the aunties chatted on the exercise machines." }
  ]},
  { type: "chips", title: "More scenes: Easy – P1/P2", groups: [
    { title: "At home", words: ["Mum is cooking in the kitchen.","The fan goes round and round.","My cat sleeps on the sofa.","Dad reads a book in his chair.","I brush my teeth before bed.","My toys are all over the floor.","The rice smells yummy.","Grandma waters her plants.","My baby brother is crying.","We eat dinner together at the table.","I hug my soft teddy bear.","The rain taps on the window."],
      ex: "The rain taps on the window. I hug my soft teddy bear.",
      note: "Easy – P1/P2. These are in the present tense. For a story about something that happened, change them to the past: “is” becomes “was”, “sleeps” becomes “slept”." },
    { title: "At school", words: ["The bell rings, and we run to the canteen.","My teacher has a kind smile.","We sit in a circle on the floor.","I write my name at the top of the page.","My friend shares her crayons with me.","The classroom is bright and clean.","We sing a song in the hall.","I read a story with my teacher.","My bag is very heavy today.","We line up at the door.","I eat my sandwich at recess.","I wave goodbye to my teacher."],
      ex: "My friend shares her crayons with me. We draw a big rainbow together.",
      note: "Easy – P1/P2." },
    { title: "Outside", words: ["The sky is blue and the sun is bright.","Birds sing in the trees.","The grass is soft and green.","I go down the slide very fast.","A butterfly lands on a flower.","The wind blows my hair.","We feed the fish in the pond.","The puddles are big and muddy.","I ride my scooter in the park.","Dad pushes me on the swing.","The ice cream uncle rings his bell.","The moon is big and round tonight."],
      ex: "A butterfly lands on a flower. I stand very still so that it will not fly away.",
      note: "Easy – P1/P2." }
  ]},
  { type: "chips", title: "More people: faces, hands and voices", groups: [
    { title: "Faces", words: ["Her eyebrows shot up so high that they almost disappeared under her fringe.","A dimple appeared in his left cheek whenever he smiled.","Freckles were sprinkled across her nose like grains of brown sugar.","His face was shiny with sweat under the hot sun.","She had a gap between her front teeth that showed when she laughed.","A thin scar ran across his chin from an old bicycle fall.","Her cheeks were flushed pink from running.","His eyebrows met in a frown above his glasses.","She had sharp, dark eyes that missed nothing.","Behind his thick glasses, his eyes looked twice their real size.","Her nose wrinkled as if she had smelt something bad.","A smudge of chocolate sat at the corner of his mouth."],
      ex: "A dimple appeared in his left cheek whenever he smiled, so it was hard to stay angry with him for long.",
      note: "Pick ONE face detail that tells us something about the person. You do not need a whole list." },
    { title: "Hands", words: ["His hands were rough and cracked from years of work at the stall.","She drummed her fingers on the table, waiting.","Grandma’s hands were spotted with age but still quick with a needle.","His knuckles turned white as he gripped the handlebars.","Her nails were painted bright pink, with one chipped at the tip.","He cracked his knuckles one by one before the game.","Ink stains covered the side of her hand.","His fingers fiddled with the zip of his jacket.","She waved both hands wildly from the back of the crowd.","He rubbed his palms together, ready for the feast.","Her hand was small and warm and sticky with sweets.","Plasters covered two of his fingers after the cooking lesson."],
      ex: "Grandma’s hands were spotted with age but still quick with a needle. In ten minutes, my torn pocket was as good as new." },
    { title: "Voices", words: ["His voice boomed down the corridor, and everyone stood up straighter.","She spoke so softly that I had to lean in to hear.","Her laugh was high and tinkly, like a little bell.","His voice was husky from cheering the day before.","She had a slow, calm way of speaking that made everyone relax.","He talked so fast that his words tripped over one another.","Her voice rose to a squeak whenever she was excited.","Grandpa’s voice was deep and crackly, like an old radio.","He mumbled into his collar so that nobody could hear.","She sang in a clear, sweet voice that filled the room.","Her voice went flat and cold, and I knew I was in trouble.","He had a habit of ending every sentence with a little laugh."],
      ex: "Her voice went flat and cold, and I knew I was in trouble. “Where,” Mum asked, “is the rest of the cake?”" }
  ]},
  { type: "chips", title: "More people: how someone moves", groups: [
    { title: "Walking", words: ["He strolled along with his hands in his pockets, whistling.","She marched into the room as if she owned it.","The old man shuffled forward, one careful step at a time.","My little cousin skipped ahead, her ponytail bouncing.","He limped slightly, trying not to put weight on his left foot.","She tiptoed past the baby’s cot.","The older boys swaggered down the corridor, laughing loudly.","He plodded up the slope, stopping every few steps to catch his breath.","She darted between the tables like a little fish.","Grandma walked with her hands clasped behind her back.","He paced the corridor, back and forth, back and forth.","She glided across the stage on her tiptoes."],
      ex: "She marched into the room as if she owned it, and every head turned to look.",
      note: "The way someone walks shows their mood. Choose the verb carefully: strolled, marched, shuffled and tiptoed all paint different people." },
    { title: "Sitting and standing", words: ["He sat bolt upright, his eyes fixed on the teacher.","She perched on the edge of her chair, ready to leap up.","Dad sprawled on the sofa, one leg dangling over the arm.","She sat cross-legged on the floor, a book open on her lap.","He leaned against the wall with his arms folded.","My brother flopped onto his bed without taking off his shoes.","She stood on tiptoe to peer over the fence.","Grandpa lowered himself into his chair with a long, contented sigh.","He hunched over his phone, his nose almost touching the screen.","She stood with her hands on her hips, waiting for an answer.","He shifted from foot to foot outside the staff room.","The baby sat up all by herself and looked very pleased about it."],
      ex: "He shifted from foot to foot outside the staff room, wishing he had told the truth on Monday." }
  ]},
  { type: "chips", title: "More scenes: smells and textures", groups: [
    { title: "Smells that set a scene", words: ["The flat smelt of incense and freshly cut flowers.","A whiff of durian floated over from the fruit stall at the end of the road.","The changing room smelt of wet tiles and shampoo.","Uncle Tan’s car smelt of new leather and peppermint.","The bus smelt of rain and damp umbrellas.","The art room smelt of paint, clay and wet newspaper.","The smell of freshly cut grass hung over the field.","A sharp, sour smell rose from the rubbish chute.","After the fogging, a thick, oily smell hung over the drain.","Grandma’s cupboard smelt of mothballs and old cloth.","Pandan cake was baking somewhere nearby, and the whole corridor smelt green and sweet.","After the fireworks, the air smelt of smoke and gunpowder."],
      ex: "Pandan cake was baking somewhere nearby, and the whole corridor smelt green and sweet. I followed my nose to Mrs Rahman’s door.",
      note: "Smell is the sense children forget most. One smell can make a place feel real." },
    { title: "Things you can feel on your skin", words: ["The cold floor tiles were a relief under my bare feet.","Sand stuck to my wet legs like sugar on a doughnut.","The sun prickled the back of my neck.","An icy blast from the air-conditioner made me shiver.","Grass tickled my ankles as I walked across the field.","My new school shoes pinched my toes.","The puppy’s fur was as soft as cotton wool.","Raindrops stung my face as I cycled into the wind.","The wooden bench was rough and splintery under my hands.","The steam from the pot was hot and damp against my face.","My fingers were sticky with mango juice.","The cool water of the stream swirled round my ankles."],
      ex: "Sand stuck to my wet legs like sugar on a doughnut, and I did not care one bit." }
  ]},
  { type: "chips", title: "More scenes: power cuts, leaks and breakdowns", groups: [
    { title: "A power cut", words: ["With a soft click, every light in the flat went out.","The fan slowed, stopped, and the room grew warm and still.","Mum felt her way along the wall to find the torch.","Across the corridor, doors opened and neighbours called, “Is your power out too?”","Candlelight threw wobbly shadows on the kitchen wall.","The fridge fell silent, and the silence felt strange.","We sat on the floor, telling stories by torchlight.","Without the hum of the air-conditioner, I could hear the crickets outside.","My phone battery was at nine per cent, and I did not dare to use it.","Down below, the whole block was dark except for a few torch beams.","When the lights blinked back on, cheers rang out from every floor.","The microwave clock flashed 00:00 over and over again."],
      ex: "With a soft click, every light in the flat went out. The fan slowed, stopped, and the room grew warm and still." },
    { title: "Leaks, floods and breakdowns", words: ["Water dripped from the ceiling into a pail with a steady plink.","A brown stain spread slowly across the ceiling board.","The lift was out of order, and the sign was stuck on with tape.","Water seeped under the bathroom door and crept along the floor.","The washing machine shuddered, groaned and stopped halfway through.","The air-conditioner dripped onto my pillow all night.","Dad lay under the sink with a torch in his mouth and a spanner in his hand.","The car coughed, spluttered and rolled to a stop at the side of the road.","We laid old towels along the floor to soak up the water.","The tap gave a gurgle and a brown splutter, then nothing.","A repairman arrived with a toolbox and a cheerful whistle.","Ten minutes later, the lift hummed back to life."],
      ex: "Dad lay under the sink with a torch in his mouth and a spanner in his hand. “Almost done,” he mumbled, as water sprayed across the floor." }
  ]},
  { type: "chips", title: "More scenes: light and colour", groups: [
    { title: "Morning light", words: ["Pale pink light crept over the tops of the blocks.","The first sunbeam slipped through the curtains and landed on my pillow.","Mist hung low over the reservoir in the early light.","The sky changed from grey to pale blue as the birds woke up.","Sunlight sparkled on the dewdrops along the fence.","The windows of the block opposite glowed gold, one after another."],
      ex: "The first sunbeam slipped through the curtains and landed on my pillow. It was Saturday, and I had nowhere to be." },
    { title: "Evening light", words: ["The sky turned the colour of a ripe mango.","Long shadows stretched across the field.","The clouds were edged with gold as the sun sank.","A purple dusk settled over the estate.","The sea shimmered like a sheet of crumpled foil.","The last light caught the top of the flagpole.","Lamps glowed in the windows as families sat down to dinner.","Swifts swooped low over the field, catching insects in the last light."],
      ex: "The sky turned the colour of a ripe mango as we cycled home along the beach." },
    { title: "Light indoors and at night", words: ["A single bulb swung above the stairs, and our shadows swayed with it.","Fairy lights twinkled around the window grille.","The glow of the fish tank lit the living room a soft blue.","Neon signs blinked red and green above the shops.","A torch beam swept across the classroom wall.","The screen glowed in the dark cinema, and three hundred faces turned towards it.","Candlelight flickered on the cake, lighting up a circle of grinning faces.","The lighthouse beam swept slowly across the dark water.","The headlights lit up the rain like silver threads.","My night light cast a small, friendly circle on the floor."],
      ex: "The glow of the fish tank lit the living room a soft blue, and I could just make out Grandpa asleep on the sofa." }
  ]},
  { type: "table", title: "More scenes: plain → vivid upgrades", head: ["Plain", "Vivid"], weakCol: 0, rows: [
    ["The room was messy.", "Clothes hung from the chair, and the bin overflowed with crumpled paper."],
    ["The market was busy.", "Stallholders shouted their prices while shoppers squeezed past one another."],
    ["The old man was kind.", "The old man wiped a stool for me and pushed his newspaper aside."],
    ["The girl was shy.", "The girl hid behind her mother’s legs and peeped out at us."],
    ["It was cold.", "I tucked my hands into my sleeves and rubbed my arms."],
    ["The baby was cute.", "The baby gave me a gummy smile and grabbed my nose."],
    ["The park was beautiful.", "Bougainvillea spilled over the fence in waves of pink and orange."],
    ["The dog was big.", "The dog was so big that its head reached the top of the gate."],
    ["The canteen was noisy.", "Spoons clattered, chairs scraped and three hundred voices talked at once."],
    ["The cake was delicious.", "The cake was so soft that it sank under my fork."],
    ["My teacher was strict.", "My teacher could silence the class just by putting down her pen."],
    ["The street was empty.", "Only a plastic bag drifted along the empty street."],
    ["He was tall.", "He had to duck his head to walk through our door."],
    ["The weather was bad.", "The wind bent the trees sideways, and the rain fell in sheets."]
  ]},
  { type: "chips", title: "More scenes: paragraph starters for describing", groups: [
    { title: "Starting a place paragraph", words: ["The first thing I noticed was the smell.","From where I stood, I could see …","At the far end of the hall, …","Right in the middle of the room stood …","Nothing had changed since my last visit, except …","It was the kind of place where …","Everywhere I looked, there was …","Stepping inside was like stepping into another world.","From the top of the stairs, …","Through the open window, …"],
      ex: "The first thing I noticed was the smell. Through the open window, I could see a huge pot of bak kut teh bubbling away." },
    { title: "Starting a person paragraph", words: ["The first thing everyone noticed about Uncle Ravi was his laugh.","You could always hear Mrs Koh before you saw her.","At first glance, she looked like any other girl in our class.","Nobody in our block was quite like Mr Goh.","If you ever need help, ask Jun Hao.","He was the smallest boy in the class, but …","Grandma had a saying for everything.","I had never seen anyone eat chilli the way Priya did.","Some people fill a room with noise; Aisha filled it with calm.","On the outside, he was fierce. On the inside, …"],
      ex: "You could always hear Mrs Koh before you saw her: the jingle of her keys, then her cheerful “Good morning!”" },
    { title: "Zooming in from wide to close", words: ["The whole field was a blur of colour. Closer, I could see …","Hundreds of parents filled the hall. In the second row, one of them was waving at me.","The market stretched out in every direction. At one small stall in the corner, …","The sea was calm and endless. Near my feet, a tiny crab scuttled into a hole.","The block towered above us, all windows and washing. On the fourth floor, one light was on.","The crowd surged towards the stage. In the middle of it, a little boy was crying.","The classroom buzzed with chatter. At the back, one desk was empty.","Fireworks filled the sky. In my sister’s eyes, each one flashed and faded."],
      ex: "The classroom buzzed with chatter. At the back, one desk was empty, and it had been empty all week.",
      note: "P4 and up. Start with the big picture, then zoom in on one small detail, like a camera." }
  ]},
  { type: "chips", title: "More scenes: trips beyond Singapore", groups: [
    { title: "Across the Causeway", words: ["Cars crawled bumper to bumper towards the Causeway checkpoint.","The immigration officer flipped through our passports and waved us on.","Rows of oil palms flashed past the car window for hours.","We stopped at a roadside stall piled high with durians and rambutans.","Grandma’s old wooden house stood on stilts, with chickens pecking underneath.","The village was so quiet that I could hear a rooster three houses away.","At the rest stop, we stretched our legs and bought steaming bowls of noodles.","The night sky over the kampung was crowded with stars."],
      ex: "The village was so quiet that I could hear a rooster three houses away. Back home, all I ever heard was traffic." },
    { title: "Somewhere cold", words: ["My breath came out in small white clouds.","Snow crunched under my boots like sugar.","My fingers were so cold that I could hardly unzip my jacket.","The mountain tops were dusted white, like icing on a cake.","Bare trees lined the road, their branches black against the grey sky.","A gust of icy wind made my eyes water.","The hot chocolate warmed my hands through the paper cup.","Everyone in the street was wrapped in thick coats and woolly hats.","The train wound through valleys of pine trees and frozen lakes.","Inside the cabin, the heater ticked and the windows fogged up."],
      ex: "My breath came out in small white clouds, and I laughed, because I had only ever seen that in films.",
      note: "P4 and up. Compare with home: a reader in Singapore understands cold best when you show how different it feels." },
    { title: "Airports and hotels", words: ["Suitcase wheels rumbled across the shiny floor.","I watched our bags disappear on the conveyor belt and hoped we would see them again.","The hotel room was so neat that I was afraid to sit on the bed.","The view from our balcony was a sea of rooftops and church spires.","The breakfast buffet stretched across the entire room.","The key card would not work, and we stood in the corridor with all our bags.","Back home, our flat looked smaller, but it smelt exactly like home."],
      ex: "Back home, our flat looked smaller, but it smelt exactly like home. I dropped my bag and flopped onto the sofa." }
  ]},
  { type: "chips", title: "More people: people at work around us", groups: [
    { title: "People who keep things running", words: ["The cleaner uncle swept the void deck in long, steady strokes before sunrise.","The bus captain nodded at each passenger as they tapped in.","A delivery rider hopped off his bike and jogged to the lift with a bag of food.","The postman pushed letters into the letterboxes with practised speed.","The security guard knew every resident’s car and waved each one through.","The gardener trimmed the hedge into a neat green box.","A nurse with a row of pens in her pocket hurried down the corridor.","The crossing guard held up her hand, and the traffic stopped for us.","The construction workers ate lunch together in the shade, laughing at a shared joke.","The repairman whistled as he tightened the last screw.","The librarian slid my books across the counter with a smile.","The school bus uncle counted us twice before he drove off."],
      ex: "The cleaner uncle swept the void deck in long, steady strokes before sunrise. I said good morning, and his whole face lit up.",
      note: "Good for compositions about kindness, gratitude or people in the community." }
  ]}
]}

]});
